// Reservation Data Processing Script for n8n (Smart Column Detection)
// Processes Dutch hotel reservation data and converts to clean JSON
// Automatically detects column positions based on header names

// Dutch to English weekday mapping
const WEEKDAY_MAP = {
  'ma': 'Monday',
  'di': 'Tuesday',
  'wo': 'Wednesday',
  'do': 'Thursday',
  'vr': 'Friday',
  'za': 'Saturday',
  'zo': 'Sunday'
};

/**
 * Detect column mappings from header row
 * @param {array} rows - Array of row objects from Excel
 * @returns {object} - Mapping of field names to column keys, plus metadata
 */
function detectColumnMapping(rows) {
  // Header keywords to look for (Dutch)
  const headerPatterns = {
    createdAt: ['Aanmaak'],
    arrival: ['Aankomst'],
    departure: ['Vertrek'],
    nights: ['Nachten'],
    rateCode: ['Prijscode'],
    channel: ['Kanaal'],
    status: ['Res. status', 'Status'],
    cancelledAt: ['Geannuleerd op', 'Geannuleerd'],
    averagePrice: ['Gem. prijs'],
    totalPrice: ['Totaal']
  };

  const mapping = {
    columns: {},
    missingColumns: [],
    usedFallback: false,
    detectionMethod: 'header'
  };

  // Search through first 10 rows to find the header row
  for (let i = 0; i < Math.min(10, rows.length); i++) {
    const row = rows[i];

    // Check each column in this row
    for (const [key, value] of Object.entries(row)) {
      if (!value || typeof value !== 'string') continue;

      const cellValue = value.trim();

      // Check against each header pattern
      for (const [fieldName, patterns] of Object.entries(headerPatterns)) {
        for (const pattern of patterns) {
          if (cellValue === pattern) {
            mapping.columns[fieldName] = key;
            break;
          }
        }
      }
    }

    // If we found the required columns, we've found the header
    if (mapping.columns.arrival && mapping.columns.departure && mapping.columns.createdAt) {
      // Check for missing optional columns
      for (const fieldName of Object.keys(headerPatterns)) {
        if (!mapping.columns[fieldName]) {
          mapping.missingColumns.push(fieldName);
        }
      }
      return mapping;
    }
  }

  // Fallback to original column positions if no header found
  console.log('Warning: Could not detect header row, using default column positions');
  mapping.usedFallback = true;
  mapping.detectionMethod = 'fallback';
  mapping.columns = {
    createdAt: '_1',
    arrival: '_2',
    departure: '_3',
    nights: '_7',
    rateCode: '_8',
    channel: '_10',
    averagePrice: '_12',
    totalPrice: '_13',
    status: '_15',
    cancelledAt: '_21'
  };

  return mapping;
}

/**
 * Parse Dutch date format "DD-MM-YY" or "DD-MM-YYYY" and return ISO date "YYYY-MM-DD"
 * @param {string} dateStr - Date string like "07-10-24" or "07-10-2024"
 * @returns {string|null} - ISO formatted date "YYYY-MM-DD" or null
 */
function parseDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') {
    return null;
  }

  // Remove any whitespace
  const cleaned = dateStr.trim();

  // Match DD-MM-YY or DD-MM-YYYY format
  const match = cleaned.match(/^(\d{2})-(\d{2})-(\d{2,4})$/);

  if (!match) {
    return null;
  }

  const day = match[1];
  const month = match[2];
  let year = match[3];

  // Convert 2-digit year to 4-digit year
  if (year.length === 2) {
    const yearNum = parseInt(year, 10);
    // Assume 20xx for years 00-50, 19xx for years 51-99
    year = yearNum <= 50 ? `20${year}` : `19${year}`;
  }

  // Return ISO format: YYYY-MM-DD
  return `${year}-${month}-${day}`;
}

/**
 * Parse datetime format "DD-MM-YYYY HH:MM:SS" and return ISO format with time "YYYY-MM-DDTHH:MM:SS"
 * @param {string} datetimeStr - DateTime string like "07-10-2024 07:21:33"
 * @returns {string|null} - ISO formatted datetime "YYYY-MM-DDTHH:MM:SS" or null
 */
function parseDatetime(datetimeStr) {
  if (!datetimeStr || typeof datetimeStr !== 'string') {
    return null;
  }

  // Match DD-MM-YYYY HH:MM:SS format
  const match = datetimeStr.trim().match(/^(\d{2})-(\d{2})-(\d{4})\s(\d{2}):(\d{2}):(\d{2})$/);

  if (!match) {
    return null;
  }

  const day = match[1];
  const month = match[2];
  const year = match[3];
  const hours = match[4];
  const minutes = match[5];
  const seconds = match[6];

  // Return ISO format without timezone: YYYY-MM-DDTHH:MM:SS
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
}

/**
 * Parse price string and return numeric value
 * @param {string} priceStr - Price string like "82,65€" or "165,30€"
 * @returns {number|null} - Numeric price value or null
 */
function parsePrice(priceStr) {
  if (!priceStr || typeof priceStr !== 'string') {
    return null;
  }

  try {
    // Remove € symbol and whitespace
    const cleaned = priceStr.replace(/€/g, '').trim();

    // Replace comma with period for decimal
    const normalized = cleaned.replace(',', '.');

    // Parse to float
    const price = parseFloat(normalized);

    // Return null if invalid number
    return isNaN(price) ? null : price;
  } catch (error) {
    return null;
  }
}

/**
 * Calculate the weekday from an ISO date string "YYYY-MM-DD"
 * @param {string} dateStr - ISO date string "YYYY-MM-DD"
 * @returns {string} - English weekday name
 */
function getWeekday(dateStr) {
  if (!dateStr) {
    return null;
  }

  try {
    // Parse ISO format YYYY-MM-DD
    const date = new Date(dateStr + 'T00:00:00Z');

    if (isNaN(date.getTime())) {
      return null;
    }

    const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    return weekdays[date.getUTCDay()];
  } catch (error) {
    return null;
  }
}

/**
 * Calculate number of nights between arrival and departure
 * @param {string} arrivalDate - ISO arrival date "YYYY-MM-DD"
 * @param {string} departureDate - ISO departure date "YYYY-MM-DD"
 * @returns {number|null} - Number of nights
 */
function calculateNights(arrivalDate, departureDate) {
  if (!arrivalDate || !departureDate) {
    return null;
  }

  try {
    // Parse ISO format YYYY-MM-DD
    const arrival = new Date(arrivalDate + 'T00:00:00Z');
    const departure = new Date(departureDate + 'T00:00:00Z');

    if (isNaN(arrival.getTime()) || isNaN(departure.getTime())) {
      return null;
    }

    const diffTime = departure - arrival;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return diffDays >= 0 ? diffDays : null;
  } catch (error) {
    return null;
  }
}

/**
 * Normalize channel name to standard format
 * @param {string} channel - Raw channel name
 * @returns {string} - Normalized channel name
 */
function normalizeChannel(channel) {
  if (!channel || typeof channel !== 'string') {
    return 'Unknown';
  }

  const normalized = channel.trim();

  // Map common variations to standard names
  const channelMap = {
    'booking-com': 'Booking.com',
    'booking.com': 'Booking.com',
    'expedia': 'Expedia',
    'hoteliers-com': 'Hoteliers.com',
    'direct-walk-in': 'Walk-in',
    'direct': 'Walk-in',
    'voordeeluitjes-ftc': 'Voordeeluitjes',
    'walk-in': 'Walk-in'
  };

  const lower = normalized.toLowerCase();
  return channelMap[lower] || normalized;
}

/**
 * Normalize rate code to standard format
 * @param {string} rateCode - Raw rate code
 * @returns {string} - Normalized rate code
 */
function normalizeRateCode(rateCode) {
  if (!rateCode || typeof rateCode !== 'string') {
    return 'Unknown';
  }

  return rateCode.trim();
}

/**
 * Check if a row is a valid data row and return validation details
 * @param {object} row - Row object
 * @param {object} mapping - Column mapping
 * @returns {object} - Validation result with isValid flag and reasons
 */
function validateDataRow(row, mapping) {
  const result = {
    isValid: true,
    errors: []
  };

  // A valid data row should have the required date fields
  const createdAt = row[mapping.columns.createdAt];
  const arrival = row[mapping.columns.arrival];
  const departure = row[mapping.columns.departure];

  if (!createdAt) {
    result.isValid = false;
    result.errors.push(`Missing creation date in column ${mapping.columns.createdAt}`);
  }

  if (!arrival) {
    result.isValid = false;
    result.errors.push(`Missing arrival date in column ${mapping.columns.arrival}`);
  }

  if (!departure) {
    result.isValid = false;
    result.errors.push(`Missing departure date in column ${mapping.columns.departure}`);
  }

  if (!result.isValid) {
    return result;
  }

  // Check if createdAt contains datetime pattern (DD-MM-YYYY HH:MM:SS)
  const datetimePattern = /^\d{2}-\d{2}-\d{4}\s\d{2}:\d{2}:\d{2}$/;
  const datePattern = /^\d{2}-\d{2}-\d{2,4}$/;

  if (!datetimePattern.test(createdAt)) {
    result.isValid = false;
    result.errors.push(`Invalid creation datetime format: "${createdAt}" (expected DD-MM-YYYY HH:MM:SS)`);
  }

  if (!datePattern.test(arrival)) {
    result.isValid = false;
    result.errors.push(`Invalid arrival date format: "${arrival}" (expected DD-MM-YY or DD-MM-YYYY)`);
  }

  if (!datePattern.test(departure)) {
    result.isValid = false;
    result.errors.push(`Invalid departure date format: "${departure}" (expected DD-MM-YY or DD-MM-YYYY)`);
  }

  return result;
}

/**
 * Process a single reservation row
 * @param {object} row - Row object from Excel
 * @param {object} mapping - Column mapping with metadata
 * @param {number} rowIndex - Row index for error reporting
 * @returns {object|null} - Processed reservation object with warnings or null
 */
function processReservation(row, mapping, rowIndex) {
  const warnings = [];
  const notes = [];

  // Add note if using fallback column detection
  if (mapping.usedFallback) {
    notes.push('Column detection used fallback positions (no header row found)');
  }

  // Add notes for missing columns
  if (mapping.missingColumns.length > 0) {
    notes.push(`Missing columns: ${mapping.missingColumns.join(', ')}`);
  }

  // Validate the row
  const validation = validateDataRow(row, mapping);

  if (!validation.isValid) {
    return null; // Skip invalid rows
  }

  // Extract and parse dates using detected column positions
  const createdAt = parseDatetime(row[mapping.columns.createdAt]);
  const arrivalDate = parseDate(row[mapping.columns.arrival]);
  const departureDate = parseDate(row[mapping.columns.departure]);
  const cancelledAt = mapping.columns.cancelledAt && row[mapping.columns.cancelledAt] ? 
    parseDatetime(row[mapping.columns.cancelledAt]) : null;

  // Check for date parsing failures
  if (!createdAt) {
    warnings.push(`Failed to parse creation date: "${row[mapping.columns.createdAt]}"`);
  }
  if (!arrivalDate) {
    warnings.push(`Failed to parse arrival date: "${row[mapping.columns.arrival]}"`);
  }
  if (!departureDate) {
    warnings.push(`Failed to parse departure date: "${row[mapping.columns.departure]}"`);
  }

  // Extract and parse prices
  const averagePrice = mapping.columns.averagePrice && row[mapping.columns.averagePrice] ? 
    parsePrice(row[mapping.columns.averagePrice]) : null;
  const totalPrice = mapping.columns.totalPrice && row[mapping.columns.totalPrice] ? 
    parsePrice(row[mapping.columns.totalPrice]) : null;

  // Add warnings for price parsing failures
  if (mapping.columns.averagePrice && row[mapping.columns.averagePrice] && averagePrice === null) {
    warnings.push(`Failed to parse average price: "${row[mapping.columns.averagePrice]}"`);
  }
  if (mapping.columns.totalPrice && row[mapping.columns.totalPrice] && totalPrice === null) {
    warnings.push(`Failed to parse total price: "${row[mapping.columns.totalPrice]}"`);
  }

  // Extract other fields
  const nightsFromData = mapping.columns.nights && row[mapping.columns.nights] ? 
    parseInt(row[mapping.columns.nights], 10) : null;
  const channel = mapping.columns.channel ? 
    normalizeChannel(row[mapping.columns.channel]) : 'Unknown';
  const rateCode = mapping.columns.rateCode ? 
    normalizeRateCode(row[mapping.columns.rateCode]) : 'Unknown';
  const status = mapping.columns.status && row[mapping.columns.status] ? 
    row[mapping.columns.status].trim() : null;

  // Calculate nights as verification (should match nightsFromData)
  const calculatedNights = calculateNights(arrivalDate, departureDate);
  const nights = nightsFromData !== null ? nightsFromData : calculatedNights;

  // Verify calculated vs provided nights if both exist
  if (nightsFromData !== null && calculatedNights !== null && nightsFromData !== calculatedNights) {
    warnings.push(`Nights mismatch: data says ${nightsFromData}, calculated ${calculatedNights}`);
  }

  // Get weekday for arrival date
  const weekdayArrival = getWeekday(arrivalDate);

  if (!weekdayArrival && arrivalDate) {
    warnings.push('Could not calculate weekday from arrival date');
  }

  // Build result object
  const result = {
    arrival_date: arrivalDate,
    nights: nights,
    departure_date: departureDate,
    created_at: createdAt,
    weekday_arrival: weekdayArrival,
    channel: channel,
    rate_code: rateCode
  };

  // Add prices if they exist
  if (averagePrice !== null) {
    result.average_price = averagePrice;
  }
  if (totalPrice !== null) {
    result.total_price = totalPrice;
  }

  // Only include cancelled_at if it exists
  if (cancelledAt) {
    result.cancelled_at = cancelledAt;
  }

  // Add warnings and notes if they exist
  if (warnings.length > 0) {
    result._warnings = warnings;
  }
  if (notes.length > 0) {
    result._notes = notes;
  }

  return result;
}

// ========== N8N EXECUTION CODE ==========

// Get input data from n8n
const items = $input.all();
const rows = items.map(item => item.json);

// Detect column mapping
const mapping = detectColumnMapping(rows);

// Process all rows
const processedReservations = [];

for (let i = 0; i < rows.length; i++) {
  const processed = processReservation(rows[i], mapping, i);

  // Only add valid reservations (skip null/invalid rows)
  if (processed) {
    processedReservations.push(processed);
  }
}

// Return in n8n format: array of objects with { json: data }
return processedReservations.map(reservation => ({
  json: reservation
}));

/**
 * Hotel Revenue Forecasting System - Module 2: Historical Analysis Engine (V10)
 *
 * Calculates:
 * - Weekday baseline averages (room nights, ADR, revenue) using all available historical
 *   data from the same calendar period (forecast window ± 4 weeks, across all available years)
 * - Revenue ratios (F&B and Other relative to RoomRevenue), per weekday
 *
 * Changes from V9:
 * - REMOVED: Narrow 90-day seasonal window → replaced with calendar-period window across all years
 * - REMOVED: Booking pace curves (reservation data captures only 30-60% of actual occupancy)
 * - REMOVED: Channel mix and leadtime distribution (not needed for AI-assisted forecast)
 */

class HistoricalAnalysisEngine {
  constructor(parsedData) {
    this.data = parsedData;
    this.analysis = {};
    this.warnings = [];
  }

  /**
   * Main analysis orchestrator
   */
  runAllAnalysis() {
    try {
      this.analysis.weekdayBaselines = this.calculateWeekdayBaselines();
      this.analysis.revenueRatios = this.calculateRevenueRatios();

      return {
        success: true,
        analysis: this.analysis,
        warnings: this.warnings
      };

    } catch (error) {
      return {
        success: false,
        error: error.message,
        warnings: this.warnings
      };
    }
  }

  /**
   * Get the day-of-year (1-based) for a date
   */
  getDayOfYear(date) {
    const start = new Date(date.getFullYear(), 0, 0);
    return Math.floor((date - start) / (1000 * 60 * 60 * 24));
  }

  /**
   * Determine the forecast calendar window (day-of-year range ± 4 weeks)
   * Returns { minDoy, maxDoy } — year-independent calendar bounds
   */
  getForecastCalendarWindow() {
    const otbData = this.data.currentHousestate;

    if (!otbData || otbData.length === 0) {
      throw new Error('CRITICAL: No current housestate data. Cannot determine forecast window.');
    }

    const firstDate = new Date(otbData[0].date);
    const lastDate = new Date(otbData[otbData.length - 1].date);

    const minDoy = this.getDayOfYear(firstDate) - 28;
    const maxDoy = this.getDayOfYear(lastDate) + 28;

    return { minDoy, maxDoy };
  }

  /**
   * Filter historical housestate records to the same calendar period across all years.
   * Uses day-of-year ± 4 weeks, so records from any available year that fall in the
   * same seasonal window are included — dramatically wider than the old 90-day single-year window.
   */
  filterToCalendarPeriod(historicalData) {
    const { minDoy, maxDoy } = this.getForecastCalendarWindow();

    return historicalData.filter(day => {
      if (day.isOutlier) return false;
      const d = new Date(day.date);
      const doy = this.getDayOfYear(d);

      // Handle year wrap-around (window crossing Dec 31 / Jan 1)
      if (minDoy <= 0) {
        return doy >= (minDoy + 365) || doy <= maxDoy;
      }
      if (maxDoy > 365) {
        return doy >= minDoy || doy <= (maxDoy - 365);
      }
      return doy >= minDoy && doy <= maxDoy;
    });
  }

  /**
   * Calculate weekday baseline averages from historical data.
   * Uses all available data within the calendar-period window (year-independent).
   */
  calculateWeekdayBaselines() {
    const historicalData = this.data.historicalHousestate;

    if (!historicalData || historicalData.length === 0) {
      throw new Error('CRITICAL: No historical housestate data available. Cannot calculate baselines.');
    }

    const filteredData = this.filterToCalendarPeriod(historicalData);

    if (filteredData.length === 0) {
      throw new Error('CRITICAL: No historical data found in calendar window. Cannot calculate baselines.');
    }

    if (filteredData.length < 30) {
      this.warnings.push(
        `WARNING: Only ${filteredData.length} days of historical data in calendar window ` +
        `(recommended: 30+). Baselines may be less reliable.`
      );
    }

    // Group by weekday
    const weekdayGroups = {
      Monday: [], Tuesday: [], Wednesday: [], Thursday: [],
      Friday: [], Saturday: [], Sunday: []
    };

    filteredData.forEach(day => {
      if (weekdayGroups[day.weekday]) {
        weekdayGroups[day.weekday].push({
          roomNights: day.roomNights,
          roomRevenue: day.roomRevenue,
          totalRevenue: day.totalRevenue
        });
      }
    });

    const baselines = {};
    const missingWeekdays = [];

    Object.keys(weekdayGroups).forEach(weekday => {
      const days = weekdayGroups[weekday];

      if (days.length === 0) {
        missingWeekdays.push(weekday);
        return;
      }

      const historicalAvgRoomNights = days.reduce((sum, d) => sum + d.roomNights, 0) / days.length;
      const historicalAvgRoomRevenue = days.reduce((sum, d) => sum + d.roomRevenue, 0) / days.length;
      const historicalAvgTotalRevenue = days.reduce((sum, d) => sum + d.totalRevenue, 0) / days.length;
      const historicalADR = historicalAvgRoomNights > 0
        ? historicalAvgRoomRevenue / historicalAvgRoomNights
        : 0;

      baselines[weekday] = {
        historicalAvgRoomNights,
        historicalAvgRoomRevenue,
        historicalAvgTotalRevenue,
        historicalADR,
        sampleSize: days.length
      };

      if (days.length < 6) {
        this.warnings.push(
          `WARNING: ${weekday} baseline has only ${days.length} samples (recommended: 6+). May be unreliable.`
        );
      }
    });

    if (missingWeekdays.length > 0) {
      throw new Error(
        `CRITICAL: Missing historical data for weekdays: ${missingWeekdays.join(', ')}. ` +
        `Need at least one data point per weekday in calendar window.`
      );
    }

    // Add metadata for debugging
    baselines._metadata = {
      daysIncluded: filteredData.length
    };

    return baselines;
  }

  /**
   * Calculate revenue ratios: F&B and Other relative to RoomRevenue, per weekday.
   * Uses same calendar-period window as baselines.
   */
  calculateRevenueRatios() {
    const historicalData = this.data.historicalHousestate;

    if (!historicalData || historicalData.length === 0) {
      throw new Error('CRITICAL: No historical housestate data. Cannot calculate revenue ratios.');
    }

    const filteredData = this.filterToCalendarPeriod(historicalData);
    const validDays = filteredData.filter(d => d.roomRevenue > 0 && d.totalRevenue > 0);

    if (validDays.length === 0) {
      throw new Error('CRITICAL: No valid revenue data in calendar window. Cannot calculate revenue ratios.');
    }

    const hasFBData = validDays.some(d => d.fbRevenue != null);
    const hasOtherData = validDays.some(d => d.otherRevenue != null);

    // Overall ratios
    const totalRoomRev = validDays.reduce((sum, d) => sum + d.roomRevenue, 0);
    const totalTotalRev = validDays.reduce((sum, d) => sum + d.totalRevenue, 0);
    const overallTotalRatio = totalTotalRev / totalRoomRev;

    let overallFBRatio, overallOtherRatio;

    if (hasFBData && hasOtherData) {
      const totalFBRev = validDays.reduce((sum, d) => sum + (d.fbRevenue || 0), 0);
      const totalOtherRev = validDays.reduce((sum, d) => sum + (d.otherRevenue || 0), 0);
      overallFBRatio = totalFBRev / totalRoomRev;
      overallOtherRatio = totalOtherRev / totalRoomRev;
    } else {
      overallFBRatio = 0;
      overallOtherRatio = overallTotalRatio - 1;
      this.warnings.push(
        'WARNING: No F&B revenue data in source. All non-room revenue treated as Other Revenue.'
      );
    }

    // Per-weekday ratios
    const weekdayRatios = {};
    ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].forEach(weekday => {
      const wkDays = validDays.filter(d => d.weekday === weekday);

      if (wkDays.length === 0) {
        weekdayRatios[weekday] = {
          totalRatio: overallTotalRatio,
          fbRatio: overallFBRatio,
          otherRatio: overallOtherRatio
        };
        this.warnings.push(
          `WARNING: No revenue data for ${weekday} in calendar window. Using overall ratios.`
        );
        return;
      }

      const wkRoomRev = wkDays.reduce((sum, d) => sum + d.roomRevenue, 0);
      const wkTotalRev = wkDays.reduce((sum, d) => sum + d.totalRevenue, 0);

      if (hasFBData && hasOtherData) {
        const wkFBRev = wkDays.reduce((sum, d) => sum + (d.fbRevenue || 0), 0);
        const wkOtherRev = wkDays.reduce((sum, d) => sum + (d.otherRevenue || 0), 0);
        weekdayRatios[weekday] = {
          totalRatio: wkTotalRev / wkRoomRev,
          fbRatio: wkFBRev / wkRoomRev,
          otherRatio: wkOtherRev / wkRoomRev
        };
      } else {
        const wkTotalRatio = wkTotalRev / wkRoomRev;
        weekdayRatios[weekday] = {
          totalRatio: wkTotalRatio,
          fbRatio: 0,
          otherRatio: wkTotalRatio - 1
        };
      }
    });

    return {
      overallTotalRatio,
      overallFBRatio,
      overallOtherRatio,
      weekdayRatios,
      hasFBData
    };
  }
}

// ============ N8N EXECUTION CODE ============
const parseResult = $input.first().json;

if (!parseResult.success) {
  throw new Error('Cannot run analysis - parsing failed');
}

const analyzer = new HistoricalAnalysisEngine(parseResult.data);
const analysisResult = analyzer.runAllAnalysis();

if (!analysisResult.success) {
  console.error('❌ ANALYSIS FAILED:', analysisResult.error);
  throw new Error('Historical analysis failed: ' + analysisResult.error);
}

const baselines = analysisResult.analysis.weekdayBaselines;
const days = Object.keys(baselines).filter(k => k !== '_metadata');
const sampleInfo = days.map(d => `${d.slice(0,3)}: ${baselines[d].sampleSize} samples, avg ${baselines[d].historicalAvgRoomNights.toFixed(0)} RN`).join(' | ');
console.log('✅ Historical analysis completed (V10) —', sampleInfo);

return [{ json: { parseResult, analysisResult } }];

/**
 * Hotel Revenue Forecasting System - Module 1: Data Parser & Validator
 * 
 * Handles:
 * - Loading and parsing all input data sources
 * - Comprehensive validation of data integrity
 * - Date parsing and normalization
 * - Data quality warnings and errors
 * - Preparation of clean data structures for forecasting engine
 * 
 * Expected Inputs:
 * 1. current_housestate.json - 90 days forward OTB data
 * 2. context.xlsx (7 sheets via separate CSVs or single object):
 *    - Hotel_Info
 *    - Events
 *    - Trends
 *    - Historical_Reservations
 *    - Historical_Housestate
 *    - Previous_Forecast
 *    - Forecast_Accuracy_History
 */

class DataParserValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.validationResults = {
      currentHousestate: { valid: false, recordCount: 0 },
      hotelInfo: { valid: false },
      events: { valid: false, recordCount: 0 },
      trends: { valid: false, recordCount: 0 },
      historicalReservations: { valid: false, recordCount: 0 },
      historicalHousestate: { valid: false, recordCount: 0 },
      previousForecast: { valid: false, recordCount: 0 },
      forecastAccuracyHistory: { valid: false, recordCount: 0 }
    };
  }

  /**
   * Main parsing function - orchestrates all data loading
   */
  parseAllData(inputData) {
    try {
      // Parse current housestate (OTB data)
      const currentHousestate = this.parseCurrentHousestate(inputData.currentHousestate);

      // Parse hotel configuration
      const hotelInfo = this.parseHotelInfo(inputData.hotelInfo);

      // Parse events
      const events = this.parseEvents(inputData.events);

      // Parse trends (may be placeholder)
      const trends = this.parseTrends(inputData.trends);

      // Parse historical reservations
      const historicalReservations = this.parseHistoricalReservations(inputData.historicalReservations);

      // Parse historical housestate
      const historicalHousestate = this.parseHistoricalHousestate(inputData.historicalHousestate);

      // Parse previous forecast
      const previousForecast = this.parsePreviousForecast(inputData.previousForecast);

      // Parse forecast accuracy history
      const forecastAccuracyHistory = this.parseForecastAccuracyHistory(inputData.forecastAccuracyHistory);

      // Flag outliers in historical data (dynamic thresholds)
      this.flagOutliers(historicalHousestate, hotelInfo);

      // Run cross-validation checks
      this.runCrossValidation({
        currentHousestate,
        hotelInfo,
        events,
        historicalReservations,
        historicalHousestate,
        previousForecast
      });

      return {
        success: this.errors.length === 0,
        data: {
          currentHousestate,
          hotelInfo,
          events,
          trends,
          historicalReservations,
          historicalHousestate,
          previousForecast,
          forecastAccuracyHistory
        },
        errors: this.errors,
        warnings: this.warnings,
        validationResults: this.validationResults
      };

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source: 'DataParser',
        message: `Fatal error during data parsing: ${error.message}`,
        timestamp: new Date().toISOString()
      });

      return {
        success: false,
        data: null,
        errors: this.errors,
        warnings: this.warnings,
        validationResults: this.validationResults
      };
    }
  }

  /**
   * Parse Current Housestate (OTB Data)
   * Expected: Array with hotel name as key containing 90 days of data
   */
  parseCurrentHousestate(rawData) {
    const source = 'CurrentHousestate';

    try {
      // Handle both array format and direct object format
      let hotelData;

      if (Array.isArray(rawData)) {
        // Find the hotel data object
        const hotelObj = rawData.find(item => {
          const keys = Object.keys(item);
          return keys.some(key => key !== 'Historical Housestats' && key !== 'Historical Reservations');
        });

        if (!hotelObj) {
          this.errors.push({
            type: 'CRITICAL',
            source,
            message: 'Could not find hotel data in current housestate array'
          });
          return [];
        }

        // Get the hotel name key
        const hotelName = Object.keys(hotelObj).find(key => 
          key !== 'Historical Housestats' && key !== 'Historical Reservations'
        );
        hotelData = hotelObj[hotelName];

      } else if (typeof rawData === 'object' && rawData !== null) {
        hotelData = rawData;
      } else {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Invalid current housestate format'
        });
        return [];
      }

      if (!Array.isArray(hotelData)) {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Current housestate hotel data is not an array'
        });
        return [];
      }

      // Validate we have close to 90 days
      if (hotelData.length < 85 || hotelData.length > 95) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Expected ~90 days of data, found ${hotelData.length} days`
        });
      }

      // Parse and validate each day
      const parsedData = hotelData.map((day, index) => {
        const parsed = {
          date: this.parseDate(day.Date, source, `row ${index + 1}`),
          weekday: this.validateWeekday(day.Weekday, source, `row ${index + 1}`),
          roomNights: this.parseNumber(day.RoomNights, source, `row ${index + 1}`, 'RoomNights'),
          roomRevenue: this.parseNumber(day.RoomRevenue, source, `row ${index + 1}`, 'RoomRevenue'),
          totalRevenue: this.parseNumber(day.TotalRevenue, source, `row ${index + 1}`, 'TotalRevenue'),
          FB_Revenue: day.FB_Revenue != null ? this.parseNumber(day.FB_Revenue, source, `row ${index + 1}`, 'FB_Revenue') : null,
          OtherRevenue: day.OtherRevenue != null ? this.parseNumber(day.OtherRevenue, source, `row ${index + 1}`, 'OtherRevenue') : null,
          rawWarnings: day._warnings || []
        };

        // Validate data quality
        if (parsed.totalRevenue < parsed.roomRevenue && parsed.totalRevenue > 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: TotalRevenue (${parsed.totalRevenue.toFixed(2)}) < RoomRevenue (${parsed.roomRevenue.toFixed(2)})`
          });
        }

        if (parsed.totalRevenue < 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: Negative TotalRevenue (${parsed.totalRevenue.toFixed(2)})`
          });
        }

        if (parsed.roomNights < 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: Negative RoomNights value (${parsed.roomNights})`
          });
        }

        return parsed;
      });

      // Ensure chronological order
      const sorted = parsedData.sort((a, b) => a.date - b.date);

      this.validationResults.currentHousestate = {
        valid: true,
        recordCount: sorted.length,
        dateRange: {
          start: sorted[0].date.toISOString().split('T')[0],
          end: sorted[sorted.length - 1].date.toISOString().split('T')[0]
        }
      };

      return sorted;

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source,
        message: `Error parsing current housestate: ${error.message}`
      });
      return [];
    }
  }

  /**
   * Parse Hotel Info
   */
  parseHotelInfo(rawData) {
    const source = 'HotelInfo';

    try {
      // Handle both array format (CSV) and single object
      let hotelData = rawData;

      if (Array.isArray(rawData)) {
        if (rawData.length === 0) {
          this.errors.push({
            type: 'CRITICAL',
            source,
            message: 'Hotel info array is empty'
          });
          return null;
        }
        hotelData = rawData[0]; // Take first row
      }

      const parsed = {
        maxRooms: this.parseNumber(hotelData.Max_Rooms, source, 'Max_Rooms', 'Max_Rooms', true),
        maxPersons: this.parseNumber(hotelData.Max_Persons, source, 'Max_Persons', 'Max_Persons'),
        minStayDuration: this.parseNumber(hotelData.Min_Stay_Duration, source, 'Min_Stay_Duration', 'Min_Stay_Duration') || 1,
        maxStayDuration: this.parseNumber(hotelData.Max_Stay_Duration, source, 'Max_Stay_Duration', 'Max_Stay_Duration') || 30,
        hotelName: String(hotelData.Hotel_Name || 'Unknown Hotel'),
        hotelAddress: String(hotelData.Hotel_Address || ''),
        hotelType: String(hotelData.Hotel_Type || 'Unknown'),
        seasonalHotel: String(hotelData.Seasonal_Hotel || 'No').toLowerCase() === 'yes',
        areaType: String(hotelData.Area_Type || 'Unknown'),
        growthTrend: this.parseNumber(hotelData.Growth_Trend, source, 'Growth_Trend', 'Growth_Trend') || 1.0
      };

      // Validate growth trend limits
      if (parsed.growthTrend < 0.5 || parsed.growthTrend > 2.0) {
        this.errors.push({
          type: 'ERROR',
          source,
          message: `Growth_Trend ${parsed.growthTrend} outside acceptable range (0.5 - 2.0)`
        });
        parsed.growthTrend = Math.max(0.5, Math.min(2.0, parsed.growthTrend));
      }

      // Validate max rooms
      if (parsed.maxRooms < 1 || parsed.maxRooms > 500) {
        this.errors.push({
          type: 'ERROR',
          source,
          message: `Max_Rooms ${parsed.maxRooms} seems unrealistic`
        });
      }

      this.validationResults.hotelInfo = { valid: true };

      return parsed;

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source,
        message: `Error parsing hotel info: ${error.message}`
      });
      return null;
    }
  }

  /**
   * Parse Events
   */
  parseEvents(rawData) {
    const source = 'Events';

    try {
      if (!Array.isArray(rawData)) {
        this.warnings.push({
          type: 'WARNING',
