      const parsed = rawData.map((event, index) => {
        return {
          eventName: String(event.Event_Name || `Event ${index + 1}`),
          startDate: this.parseDate(event.Start_Date, source, `row ${index + 1}`),
          endDate: this.parseDate(event.End_Date, source, `row ${index + 1}`),
