// ============ HISTORICAL ANALYSIS OUTPUT (ARRAY-STRUCTURE) ============
const input = $input.first().json;

const parseResult = input.parseResult;
const analysisResult = input.analysisResult;

if (!analysisResult || !analysisResult.success) {
  throw new Error('Cannot output historical analysis - analysis failed');
}

const analysis = analysisResult.analysis || {};
const hotelInfo = (parseResult && parseResult.data && parseResult.data.hotelInfo) || {};

const hotelName = hotelInfo.hotelName || hotelInfo.Hotel_Name || 'Unknown Hotel';
const asOfDate = new Date().toISOString().split('T')[0];

// ================== 1. Weekday baselines ==================
const weekdayBaselinesRaw = analysis.weekdayBaselines || {};
const WeekdayBaselines = Object.keys(weekdayBaselinesRaw).map(weekday => {
  const stats = weekdayBaselinesRaw[weekday] || {};
  return {
    Weekday: weekday,
    Avg_Room_Nights: parseFloat(Number(stats.avgRoomNights || 0).toFixed(2)),
    Avg_Room_Revenue: parseFloat(Number(stats.avgRoomRevenue || 0).toFixed(2)),
    Avg_Total_Revenue: parseFloat(Number(stats.avgTotalRevenue || 0).toFixed(2)),
    Avg_ADR: parseFloat(Number(stats.avgADR || 0).toFixed(2)),
    Sample_Size: stats.sampleSize ?? null
  };
});

// ================== 2. Channel mix ==================
const channelMixRaw = analysis.channelMix || {};
const ChannelMix = Object.keys(channelMixRaw).map(channel => {
  const mix = channelMixRaw[channel] || {};
  return {
    Channel: channel,
    LastYear_Pct: parseFloat(Number(mix.lastYear || 0).toFixed(3)),
    Forecast_Pct: parseFloat(Number(mix.forecast || 0).toFixed(3))
  };
});

// ================== 3. Leadtime distribution ==================
const ld = analysis.leadtimeDistribution || {};
const buckets = ld.buckets || {};
const LeadtimeDistributionBuckets = Object.keys(buckets).map(bucketName => ({
  Bucket: bucketName, // bv. "0-1d", "2-7d"
  Share_Pct: parseFloat(Number(buckets[bucketName] || 0).toFixed(3)),
  Sample_Size: ld.sampleSize ?? null
}));

const LeadtimeSummary = (ld.avgLeadtime != null)
  ? {
      Avg_Leadtime_Days: parseFloat(Number(ld.avgLeadtime || 0).toFixed(2)),
      Sample_Size: ld.sampleSize ?? null
    }
  : null;

// ================== 4. Leadtime curves per weekday ==================
const leadtimeCurvesRaw = analysis.leadtimeCurves || {};
const LeadtimeCurvesByWeekday = [];

Object.keys(leadtimeCurvesRaw).forEach(weekday => {
  const curve = leadtimeCurvesRaw[weekday] || {}; // keys zoals "day0", "day1", "day2", ...
  Object.keys(curve).forEach(key => {
    const daysBeforeArrival = Number(key.replace('day', '')) || 0;
    LeadtimeCurvesByWeekday.push({
      Weekday: weekday,
      Days_Before_Arrival: daysBeforeArrival,
      Cumulative_Pct: parseFloat(Number(curve[key] || 0).toFixed(3))
    });
  });
});

// ================== 4b. Overall leadtime curve ==================
const overallCurveRaw = analysis.overallLeadtimeCurve || {};
const OverallLeadtimeCurve = Object.keys(overallCurveRaw).map(key => {
  const daysBeforeArrival = Number(key.replace('day', '')) || 0;
  return {
    Days_Before_Arrival: daysBeforeArrival,
    Cumulative_Pct: parseFloat(Number(overallCurveRaw[key] || 0).toFixed(3))
  };
});

// ================== 5. Revenue ratios ==================
const rr = analysis.revenueRatios || {};

const RevenueRatioOverall = (rr.overallRatio != null)
  ? parseFloat(Number(rr.overallRatio || 0).toFixed(4))
  : null;

const weekdayRatiosRaw = rr.weekdayRatios || {};
const RevenueRatiosByWeekday = Object.keys(weekdayRatiosRaw).map(weekday => ({
  Weekday: weekday,
  Ratio_TotalRev_to_RoomRev: parseFloat(Number(weekdayRatiosRaw[weekday] || 0).toFixed(4))
}));

// ================== 6. Warnings ==================
const Warnings = (analysisResult.warnings || []).map(msg => String(msg));

// ================== BUILD SINGLE OUTPUT OBJECT ==================
const output = {
  Hotel_Name: hotelName,
  As_Of_Date: asOfDate,

  WeekdayBaselines,
  ChannelMix,
  LeadtimeDistributionBuckets,
  LeadtimeSummary,
  LeadtimeCurvesByWeekday,
  OverallLeadtimeCurve,
  RevenueRatioOverall,
  RevenueRatiosByWeekday,
  Warnings
};

